import { parseBoardCode } from './deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from './game.ts';
import type { GameState } from './game.ts';

export interface TournamentPlayer {
  readonly id: number;
  readonly name: string;
}

export interface TournamentResult {
  readonly moves: number;
  readonly elapsedMs: number;
}

export interface TournamentMatch {
  readonly players: readonly [number | null, number | null];
  readonly boardCode: string;
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winnerId: number | null;
}

export interface Tournament {
  readonly id: string;
  readonly size: number;
  readonly players: readonly TournamentPlayer[];
  readonly rounds: readonly (readonly TournamentMatch[])[];
  readonly currentRound: number;
  readonly currentMatch: number;
  readonly turn: 0 | 1;
  readonly status: 'active' | 'complete';
  readonly championId: number | null;
  readonly createdAt: number;
  readonly completedAt: number | null;
}

export interface TournamentDraft {
  readonly playerCount: 4 | 8;
  readonly names: readonly string[];
}

export function currentTournamentMatch(tournament: Tournament): TournamentMatch {
  const round = tournament.rounds[tournament.currentRound];
  const match = round?.[tournament.currentMatch];
  if (!match) throw new Error('Tournament match is missing.');
  return match;
}

export function createTournament(
  names: readonly string[],
  size: number,
  id: string,
  createdAt: number,
  nextBoardCode: (size: number, previousSeed?: number) => string,
): Tournament {
  const players = names.map((name, playerId) => ({ id: playerId, name }));
  const rounds: TournamentMatch[][] = [];
  let previousSeed: number | undefined;
  for (let matchCount = names.length / 2; matchCount >= 1; matchCount /= 2) {
    const matches: TournamentMatch[] = [];
    for (let matchIndex = 0; matchIndex < matchCount; matchIndex += 1) {
      const boardCode = nextBoardCode(size, previousSeed);
      previousSeed = parseBoardCode(boardCode)?.seed;
      const firstPlayer = rounds.length === 0 ? matchIndex * 2 : null;
      const secondPlayer = rounds.length === 0 ? matchIndex * 2 + 1 : null;
      matches.push({
        players: [firstPlayer, secondPlayer],
        boardCode,
        results: [null, null],
        winnerId: null,
      });
    }
    rounds.push(matches);
  }
  return {
    id,
    size,
    players,
    rounds,
    currentRound: 0,
    currentMatch: 0,
    turn: 0,
    status: 'active',
    championId: null,
    createdAt,
    completedAt: null,
  };
}

export function recordTournamentResult(
  tournament: Tournament,
  result: TournamentResult,
): Tournament {
  const match = currentTournamentMatch(tournament);
  if (tournament.status !== 'active' || match.results[tournament.turn]) return tournament;
  const results: [TournamentResult | null, TournamentResult | null] = [...match.results];
  results[tournament.turn] = result;
  return replaceCurrentMatch(tournament, { ...match, results });
}

export function advanceTournamentTurn(tournament: Tournament): Tournament {
  const match = currentTournamentMatch(tournament);
  if (tournament.status !== 'active' || tournament.turn !== 0 || !match.results[0])
    return tournament;
  return { ...tournament, turn: 1 };
}

export function advanceTournament(tournament: Tournament, completedAt: number): Tournament {
  const match = currentTournamentMatch(tournament);
  const first = match.players[0];
  const second = match.players[1];
  const firstResult = match.results[0];
  const secondResult = match.results[1];
  if (
    tournament.status !== 'active' ||
    first === null ||
    second === null ||
    !firstResult ||
    !secondResult
  )
    return tournament;
  const winnerId =
    firstResult.moves < secondResult.moves
      ? first
      : secondResult.moves < firstResult.moves
        ? second
        : firstResult.elapsedMs <= secondResult.elapsedMs
          ? first
          : second;
  const rounds = tournament.rounds.map((round) => [...round]);
  const currentRound = rounds[tournament.currentRound];
  if (!currentRound) return tournament;
  currentRound[tournament.currentMatch] = { ...match, winnerId };
  if (tournament.currentRound === rounds.length - 1) {
    return {
      ...tournament,
      rounds,
      status: 'complete',
      championId: winnerId,
      completedAt,
    };
  }
  const nextRound = rounds[tournament.currentRound + 1];
  const feeder = nextRound?.[Math.floor(tournament.currentMatch / 2)];
  if (!nextRound || !feeder) return tournament;
  const nextPlayers: [number | null, number | null] = [...feeder.players];
  nextPlayers[tournament.currentMatch % 2] = winnerId;
  nextRound[Math.floor(tournament.currentMatch / 2)] = { ...feeder, players: nextPlayers };
  const isLastMatch = tournament.currentMatch === currentRound.length - 1;
  return {
    ...tournament,
    rounds,
    currentRound: isLastMatch ? tournament.currentRound + 1 : tournament.currentRound,
    currentMatch: isLastMatch ? 0 : tournament.currentMatch + 1,
    turn: 0,
  };
}

export function resultForGame(game: GameState): TournamentResult {
  return { moves: game.moves, elapsedMs: game.elapsedMs };
}

export function isValidTournamentResult(value: unknown, size: number): value is TournamentResult {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.keys(value).length === 2 &&
    Object.hasOwn(value, 'moves') &&
    Object.hasOwn(value, 'elapsedMs') &&
    Number.isSafeInteger(Reflect.get(value, 'moves')) &&
    Number(Reflect.get(value, 'moves')) >= size ** 2 / 2 &&
    Number(Reflect.get(value, 'moves')) <= MOVES_MAX &&
    Number.isFinite(Reflect.get(value, 'elapsedMs')) &&
    Number(Reflect.get(value, 'elapsedMs')) >= 0 &&
    Number(Reflect.get(value, 'elapsedMs')) <= ELAPSED_MAX_MS
  );
}

function replaceCurrentMatch(tournament: Tournament, match: TournamentMatch): Tournament {
  const rounds = tournament.rounds.map((round) => [...round]);
  const round = rounds[tournament.currentRound];
  if (!round) return tournament;
  round[tournament.currentMatch] = match;
  return { ...tournament, rounds };
}
import { isValidSize, parseBoardCode } from './deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from './saved-format.ts';
import { isValidTournamentResult } from './tournament.ts';
import type { Tournament, TournamentMatch, TournamentPlayer } from './tournament.ts';

const TOURNAMENT_KEYS = [
  'id',
  'size',
  'players',
  'rounds',
  'currentRound',
  'currentMatch',
  'turn',
  'status',
  'championId',
  'createdAt',
  'completedAt',
] as const;
const DATE_MAX_MS = 8_640_000_000_000_000;

export function isValidTournament(value: unknown): value is Tournament {
  if (!isJsonObject(value) || !hasExactKeys(value, TOURNAMENT_KEYS)) return false;
  if (
    typeof value.id !== 'string' ||
    value.id.length === 0 ||
    value.id.length > 100 ||
    typeof value.size !== 'number' ||
    !isValidSize(value.size) ||
    !isNonnegativeSafeInteger(value.createdAt) ||
    value.createdAt > DATE_MAX_MS ||
    (value.completedAt !== null &&
      (!isNonnegativeSafeInteger(value.completedAt) || value.completedAt > DATE_MAX_MS)) ||
    !isNonnegativeSafeInteger(value.currentRound) ||
    !isNonnegativeSafeInteger(value.currentMatch) ||
    (value.turn !== 0 && value.turn !== 1) ||
    (value.status !== 'active' && value.status !== 'complete')
  )
    return false;
  if (!isUnknownArray(value.players) || ![4, 8].includes(value.players.length)) return false;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.players.length; index += 1) {
    const player = value.players[index];
    if (
      !isJsonObject(player) ||
      !hasExactKeys(player, ['id', 'name']) ||
      !isNonnegativeSafeInteger(player.id) ||
      player.id !== index ||
      typeof player.name !== 'string' ||
      player.name.trim().length === 0 ||
      player.name.length > 60
    )
      return false;
    players.push({ id: player.id, name: player.name });
  }
  if (!isUnknownArray(value.rounds) || value.rounds.length !== Math.log2(players.length))
    return false;
  const rounds: TournamentMatch[][] = [];
  for (let roundIndex = 0; roundIndex < value.rounds.length; roundIndex += 1) {
    const valueRound = value.rounds[roundIndex];
    const expectedCount = players.length / 2 ** (roundIndex + 1);
    if (!isUnknownArray(valueRound) || valueRound.length !== expectedCount) return false;
    const round: TournamentMatch[] = [];
    for (const item of valueRound) {
      if (!isValidMatch(item, Number(value.size), players.length)) return false;
      round.push(item);
    }
    rounds.push(round);
  }
  const lastRound = rounds.at(-1);
  const currentRound = rounds[value.currentRound];
  const currentMatch = currentRound?.[value.currentMatch];
  if (!currentMatch || currentMatch.players[0] === null || currentMatch.players[1] === null)
    return false;
  for (let roundIndex = 0; roundIndex < rounds.length; roundIndex += 1) {
    const round = rounds[roundIndex];
    const priorRound = rounds[roundIndex - 1];
    if (!round) return false;
    for (let matchIndex = 0; matchIndex < round.length; matchIndex += 1) {
      const match = round[matchIndex];
      if (!match) return false;
      const expectedPlayers =
        roundIndex === 0
          ? [matchIndex * 2, matchIndex * 2 + 1]
          : [
              priorRound?.[matchIndex * 2]?.winnerId ?? null,
              priorRound?.[matchIndex * 2 + 1]?.winnerId ?? null,
            ];
      if (match.players[0] !== expectedPlayers[0] || match.players[1] !== expectedPlayers[1])
        return false;
      const beforeCurrent =
        roundIndex < value.currentRound ||
        (roundIndex === value.currentRound && matchIndex < value.currentMatch);
      const afterCurrent =
        roundIndex > value.currentRound ||
        (roundIndex === value.currentRound && matchIndex > value.currentMatch);
      if (beforeCurrent && (match.winnerId === null || !match.results[0] || !match.results[1]))
        return false;
      if (afterCurrent && (match.winnerId !== null || match.results[0] || match.results[1]))
        return false;
      if (
        value.status === 'active' &&
        roundIndex === value.currentRound &&
        matchIndex === value.currentMatch
      ) {
        if (match.winnerId !== null) return false;
        if (value.turn === 0 && match.results[1] !== null) return false;
        if (value.turn === 1 && match.results[0] === null) return false;
      }
    }
  }
  if (value.status === 'active') {
    return value.championId === null && value.completedAt === null;
  }
  return (
    value.currentRound === rounds.length - 1 &&
    value.currentMatch === 0 &&
    value.championId !== null &&
    value.completedAt !== null &&
    rounds.every((round) => round.every((match) => match.winnerId !== null)) &&
    value.championId === lastRound?.[0]?.winnerId
  );
}

function isValidMatch(value: unknown, size: number, playerCount: number): value is TournamentMatch {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['players', 'boardCode', 'results', 'winnerId']) ||
    typeof value.boardCode !== 'string' ||
    parseBoardCode(value.boardCode)?.size !== size ||
    !isUnknownArray(value.players) ||
    value.players.length !== 2 ||
    !isPlayerId(value.players[0], playerCount, true) ||
    !isPlayerId(value.players[1], playerCount, true) ||
    (value.players[0] !== null && value.players[0] === value.players[1]) ||
    !isUnknownArray(value.results) ||
    value.results.length !== 2 ||
    !isUnknownArray(value.results) ||
    (value.results[0] !== null && !isValidTournamentResult(value.results[0], size)) ||
    (value.results[1] !== null && !isValidTournamentResult(value.results[1], size)) ||
    !isPlayerId(value.winnerId, playerCount, true)
  )
    return false;
  for (let slot = 0; slot < 2; slot += 1) {
    if (value.players[slot] === null && value.results[slot] !== null) return false;
  }
  if (value.winnerId === null) return value.results[0] === null || value.results[1] === null;
  const first = value.results[0];
  const second = value.results[1];
  if (!first || !second) return false;
  const expectedWinner =
    first.moves < second.moves
      ? value.players[0]
      : second.moves < first.moves
        ? value.players[1]
        : first.elapsedMs <= second.elapsedMs
          ? value.players[0]
          : value.players[1];
  return value.winnerId === expectedWinner;
}

function isPlayerId(
  value: unknown,
  playerCount: number,
  allowNull: boolean,
): value is number | null {
  return (allowNull && value === null) || (isNonnegativeSafeInteger(value) && value < playerCount);
}

function isUnknownArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

import { useRef, useState } from 'react';
import { activateCard, createGame, isWon } from './game.ts';
import { decodeTournament, encodeTournament } from './tournament-format.ts';
import {
  advanceTournament,
  advanceTournamentTurn,
  createTournament,
  currentTournamentMatch,
  recordTournamentResult,
  resultForGame,
} from './tournament.ts';
import { readPastTournaments, writePastTournaments } from './tournament-storage.ts';
import { browserStore } from './session/use-saved-preferences.ts';
import { initialSession, replaceGame } from './session/session.ts';
import { useSessionClock } from './session/use-session-clock.ts';
import { freshBoardCode } from './session/fresh-board.ts';
import type { Session } from './session/session.ts';
import type { Tournament, TournamentDraft } from './tournament.ts';

interface TournamentController {
  readonly draft: TournamentDraft;
  readonly tournament: Tournament | null;
  readonly session: Session;
  readonly past: readonly Tournament[];
  readonly json: string;
  readonly notice: string;
  readonly turnReady: boolean;
  setPlayerCount(count: 4 | 8): void;
  setName(index: number, name: string): void;
  setJson(value: string): void;
  start(): void;
  startTurn(): void;
  activate(index: number): void;
  nextTurn(): void;
  nextMatch(): void;
  exportTournament(): void;
  loadTournament(): void;
}

export function useTournament(size: number, boardCode: string): TournamentController {
  const [store] = useState(browserStore);
  const [draft, setDraft] = useState<TournamentDraft>({
    playerCount: 4,
    names: ['', '', '', ''],
  });
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [past, setPast] = useState(() => readPastTournaments(store));
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [turnReady, setTurnReady] = useState(false);
  const [session, setSession] = useState(() => initialSession(boardCode, { size, bestMoves: {} }));
  const current = useRef(session);
  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }
  const clock = useSessionClock(session, current, commit);

  function prepareTurn(code: string): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    setTurnReady(false);
  }

  function setPlayerCount(count: 4 | 8): void {
    setDraft((previous) => ({
      playerCount: count,
      names: Array.from({ length: count }, (_, index) => previous.names[index] ?? ''),
    }));
  }

  function setName(index: number, name: string): void {
    setDraft((previous) => ({
      ...previous,
      names: previous.names.map((currentName, currentIndex) =>
        currentIndex === index ? name : currentName,
      ),
    }));
  }

  function start(): void {
    if (tournament) return;
    const names = draft.names.slice(0, draft.playerCount).map((name) => name.trim());
    if (names.some((name) => name.length === 0 || name.length > 60)) {
      setNotice('Enter a name of 1 to 60 characters for every player.');
      return;
    }
    const started = createTournament(names, size, crypto.randomUUID(), Date.now(), freshBoardCode);
    setDraft({ playerCount: draft.playerCount, names });
    setTournament(started);
    setNotice('');
    prepareTurn(currentTournamentMatch(started).boardCode);
  }

  function activate(index: number): void {
    clock.synchronize();
    const previous = current.current;
    const game = activateCard(previous.game, index);
    if (game === previous.game) return;
    commit({ ...previous, game });
    if (isWon(game)) {
      setTournament((active) =>
        active ? recordTournamentResult(active, resultForGame(game)) : active,
      );
    }
  }

  function nextTurn(): void {
    if (!tournament) return;
    const next = advanceTournamentTurn(tournament);
    if (next === tournament) return;
    setTournament(next);
    prepareTurn(currentTournamentMatch(next).boardCode);
  }

  function nextMatch(): void {
    if (!tournament) return;
    const next = advanceTournament(tournament, Date.now());
    if (next === tournament) return;
    setTournament(next);
    if (next.status === 'complete') {
      const nextPast = [next, ...past.filter((item) => item.id !== next.id)];
      setPast(nextPast);
      writePastTournaments(store, nextPast);
      return;
    }
    prepareTurn(currentTournamentMatch(next).boardCode);
  }

  function exportTournament(): void {
    setJson(
      encodeTournament(draft, tournament, tournament?.status === 'active' ? session.game : null),
    );
  }

  function loadTournament(): void {
    const loaded = decodeTournament(json);
    if (!loaded) {
      setNotice('Invalid tournament JSON.');
      return;
    }
    setDraft(loaded.draft);
    setTournament(loaded.tournament);
    setTurnReady(Boolean(loaded.game?.started || (loaded.game && isWon(loaded.game))));
    if (loaded.game) {
      clock.reset();
      commit({
        ...current.current,
        game: loaded.game,
        paused: false,
        generation: current.current.generation + 1,
        feedback: '',
        loadNotice: '',
        announcement: current.current.announcement + 1,
        celebration: false,
      });
    }
    if (loaded.tournament?.status === 'complete') {
      const nextPast = [
        loaded.tournament,
        ...past.filter((item) => item.id !== loaded.tournament?.id),
      ];
      setPast(nextPast);
      writePastTournaments(store, nextPast);
    }
    setNotice('Tournament loaded.');
  }

  return {
    draft,
    tournament,
    session,
    past,
    json,
    notice,
    turnReady,
    setPlayerCount,
    setName,
    setJson,
    start,
    startTurn: () => setTurnReady(true),
    activate,
    nextTurn,
    nextMatch,
    exportTournament,
    loadTournament,
  };
}
